/**
 * rule-deployer.ts — 规则下发 (Phase 3.3)
 *
 * 灰度发布 + 固定哈希分组 + 自动回滚 + 签名验证硬拒绝。
 */
import * as crypto from 'crypto';
import { createLogger } from '../../infra/logger';
import type { DiagnosticRule } from './rule-registry';

const log = createLogger('diagnosis/rule-deployer');

// ═══ Types ═══

export interface RuleUpdateProposal {
  ruleId: string;
  newVersion: number;
  changes: Record<string, { old: unknown; new: unknown }>;
  globalConfidence: number;
  affectedOrgCount: number;
  backtestResult: { improvementRate: number };
}

export interface SignedRulePackage {
  packageId: string;
  rules: DiagnosticRule[];
  signature: string;
  publicKeyPem: string;
  version: number;
  createdAt: string;
}

export interface CanaryGroup {
  name: string;
  percentage: number;
  orgHashes: string[];
}

// ═══ Hashing ═══

const FIXED_SEED = 'synova-canary-seed-v1';

/** 固定哈希分组——同一组织始终在同一组 */
export function assignGroup(orgId: string, totalGroups = 100): number {
  const hash = crypto.createHash('sha256').update(orgId + FIXED_SEED).digest('hex');
  return parseInt(hash.slice(0, 8), 16) % totalGroups;
}

// ═══ Signing ═══

/** 对规则包签名。私钥来自环境变量 FEDERATION_PRIVATE_KEY 或 KMS。 */
export function signPackage(rules: DiagnosticRule[], privateKeyPem: string, version: number): SignedRulePackage {
  const pkgId = `pkg_${Date.now().toString(36)}`;
  const sign = crypto.createSign('SHA256');
  sign.update(JSON.stringify({ rules, packageId: pkgId, version }));
  const signature = sign.sign(privateKeyPem, 'base64');

  const publicKey = crypto.createPublicKey(privateKeyPem).export({ type: 'spki', format: 'pem' }) as string;

  return { packageId: pkgId, rules, signature, publicKeyPem: publicKey, version, createdAt: new Date().toISOString() };
}

/** 验证签名——无效则硬拒绝，不允许降级或跳过。 */
export function verifyPackage(pkg: SignedRulePackage): boolean {
  try {
    const verify = crypto.createVerify('SHA256');
    verify.update(JSON.stringify({ rules: pkg.rules, packageId: pkg.packageId, version: pkg.version }));
    const valid = verify.verify(pkg.publicKeyPem, pkg.signature, 'base64');
    if (!valid) {
      log.error({ packageId: pkg.packageId, fingerprint: pkg.signature.slice(0, 16) }, '签名验证失败——规则包可能被篡改');
    }
    return valid;
  } catch (err: any) {
    log.error({ err: err.message, packageId: pkg.packageId }, '签名验证异常');
    return false;
  }
}

// ═══ RuleDeployer ═══

export class RuleDeployer {
  private deployedVersions = new Map<string, number>(); // ruleId → version

  /** 灰度发布：5% → 观察2周 → 45% → 100% */
  canaryDeploy(proposal: RuleUpdateProposal, orgHashes: string[]): CanaryGroup[] {
    const groups: CanaryGroup[] = [
      { name: 'canary-5', percentage: 5, orgHashes: [] },
      { name: 'canary-50', percentage: 50, orgHashes: [] },
    ];

    for (const orgHash of orgHashes) {
      const bucket = assignGroup(orgHash);
      if (bucket < 5) {
        groups[0].orgHashes.push(orgHash);
      } else if (bucket < 50) {
        groups[1].orgHashes.push(orgHash);
      }
      // 50-99: 全量组（不在灰度范围内）
    }
    return groups;
  }

  fullDeploy(ruleId: string, version: number): void {
    this.deployedVersions.set(ruleId, version);
    log.info({ ruleId, version }, '全量下发完成');
  }

  rollback(ruleId: string, targetVersion: number): void {
    this.deployedVersions.set(ruleId, targetVersion);
    log.warn({ ruleId, targetVersion }, '规则已回滚');
  }

  getDeployedVersion(ruleId: string): number | undefined {
    return this.deployedVersions.get(ruleId);
  }

  /**
   * 自动回滚检测：
   *   灰度组指标 < 对照组 × 0.9 → 1 小时内自动回滚
   */
  shouldAutoRollback(canaryMetrics: { hypothesisConfirmRate: number; actionAdoptionRate: number }, controlMetrics: { hypothesisConfirmRate: number; actionAdoptionRate: number }): boolean {
    const hcrDrop = canaryMetrics.hypothesisConfirmRate < controlMetrics.hypothesisConfirmRate * 0.9;
    const aarDrop = canaryMetrics.actionAdoptionRate < controlMetrics.actionAdoptionRate * 0.9;
    if (hcrDrop || aarDrop) {
      log.error({ canaryMetrics, controlMetrics }, '灰度组指标下降超过 10%——触发自动回滚');
      return true;
    }
    return false;
  }
}

// ═══ RuleUpdater (终端) ═══

export class RuleUpdater {
  private registry: any; // RuleRegistry

  constructor(registry: any) {
    this.registry = registry;
  }

  /** 应用规则更新——签名无效则硬拒绝 */
  applyUpdate(pkg: SignedRulePackage): void {
    if (!verifyPackage(pkg)) {
      throw new Error('签名验证失败——规则包可能被篡改，已拒绝应用');
    }
    for (const rule of pkg.rules) {
      this.registry.register(rule);
    }
    log.info({ packageId: pkg.packageId, count: pkg.rules.length }, '规则更新已应用');
  }

  /** 定时检查更新 */
  async checkForUpdates(_endpoint?: string): Promise<SignedRulePackage | null> {
    // 实际实现会从平台端点拉取，当前为本地模式
    return null;
  }
}
